#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXN 200005
#define HASH 262144

typedef struct Node Node;
typedef struct Entry Entry;

struct Entry {
    char *key;
    Node *val;
    Entry *next;
};

struct Node {
    int is_string;      /* 1 = string, 0 = object */
    char *str;          /* valid if is_string */
    Entry *table[HASH]; /* valid if object */
};

static char *lines[MAXN];
static int nlines;
static char query[MAXN];

static unsigned long long hfunc(const char *s) {
    unsigned long long h = 1469598103934665603ULL;
    while (*s) {
        h ^= (unsigned char)*s++;
        h *= 1099511628211ULL;
    }
    return h & (HASH - 1);
}

static Node *new_object(void) {
    Node *x = (Node *)calloc(1, sizeof(Node));
    x->is_string = 0;
    x->str = NULL;
    return x;
}

static Node *new_string(const char *s) {
    Node *x = (Node *)calloc(1, sizeof(Node));
    x->is_string = 1;
    x->str = strdup(s);
    return x;
}

static void obj_put(Node *obj, char *key, Node *val) {
    unsigned long long h = hfunc(key);
    Entry *e = (Entry *)malloc(sizeof(Entry));
    e->key = key;
    e->val = val;
    e->next = obj->table[h];
    obj->table[h] = e;
}

static Node *obj_get(Node *obj, const char *key) {
    if (!obj || obj->is_string) return NULL;
    unsigned long long h = hfunc(key);
    Entry *e = obj->table[h];
    while (e) {
        if (strcmp(e->key, key) == 0) return e->val;
        e = e->next;
    }
    return NULL;
}

static int count_indent(const char *s) {
    int c = 0;
    while (*s == ' ') c++;
    return c;
}

static int is_key_char(char c) {
    return isalpha((unsigned char)c) || isdigit((unsigned char)c) || c == '_';
}

static char *dup_range(const char *l, const char *r) {
    int len = (int)(r - l);
    char *s = (char *)malloc(len + 1);
    memcpy(s, l, len);
    s[len] = 0;
    return s;
}

/* parse block starting at line *idx, with exact indentation 'indent' */
static Node *parse_block(int *idx, int indent) {
    Node *obj = new_object();

    while (*idx < nlines) {
        char *line = lines[*idx];
        int ind = count_indent(line);
        if (ind < indent) break;
        if (ind > indent) {
            /* malformed for this grammar, but skip safely */
            (*idx)++;
            continue;
        }

        char *p = line + indent;
        char *kbeg = p;
        while (*p && is_key_char(*p)) p++;
        char *kend = p;

        if (kend == kbeg || *p != ':') {
            (*idx)++;
            continue;
        }
        char *key = dup_range(kbeg, kend);
        p++; /* skip ':' */

        if (*p == ' ') {
            p++;
            /* string value: rest of line */
            Node *val = new_string(p);
            obj_put(obj, key, val);
            (*idx)++;
        } else if (*p == '\0') {
            /* nested object */
            (*idx)++;
            Node *val = parse_block(idx, indent + 2);
            obj_put(obj, key, val);
        } else {
            /* unexpected, treat as empty string */
            Node *val = new_string(p);
            obj_put(obj, key, val);
            (*idx)++;
        }
    }

    return obj;
}

int main(void) {
