public class Main {

    static class YamlParser {
        private final String input;
        private int pos;

        YamlParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        // Skip whitespace and newlines
        private void skipWhitespace() {
            while (pos < input.length() && (input.charAt(pos) == ' ' || input.charAt(pos) == '\n')) {
                pos++;
            }
        }

        // Parse the entire YAML document
        Map<String, Object> parse() {
            skipWhitespace();
            return parseMapping(0);
        }

        // Parse a mapping at given indentation level
        private Map<String, Object> parseMapping(int indent) {
            Map<String, Object> map = new LinkedHashMap<>();

            while (pos < input.length()) {
                skipWhitespace();
                if (pos >= input.length()) break;

                // Check if we've reached end of current mapping (less indentation)
                int currentIndent = getCurrentIndent();
                if (currentIndent < indent) break;
                if (currentIndent > indent) {
                    // This shouldn't happen in well-formed input, but skip
                    pos++;
                    continue;
                }

                // Parse key
                StringBuilder key = new StringBuilder();
                while (pos < input.length() && input.charAt(pos) != ':' && input.charAt(pos) != '\n') {
                    key.append(input.charAt(pos));
                    pos++;
                }

                if (pos >= input.length() || input.charAt(pos) != ':') {
                    break; // malformed
                }
                pos++; // skip ':'

                skipWhitespace();

                // Check if value is on same line
                if (pos < input.length() && input.charAt(pos) != '\n') {
                    // It's a scalar value (string)
                    StringBuilder value = new StringBuilder();
                    while (pos < input.length() && input.charAt(pos) != '\n') {
                        value.append(input.charAt(pos));
                        pos++;
                    }
                    map.put(key.toString().trim(), value.toString().trim());
                } else {
                    // Value is on next line(s) - it's a mapping
                    // Skip the newline
                    if (pos < input.length() && input.charAt(pos) == '\n') {
                        pos++;
                    }

                    // Calculate indentation of first child
                    int childIndent = getCurrentIndent();
                    if (childIndent > currentIndent) {
                        map.put(key.toString().trim(), parseMapping(childIndent));
                    } else {
                        // Empty mapping or no children
                        map.put(key.toString().trim(), new LinkedHashMap<String, Object>());
                    }
                }
            }

            return map;
        }

        private int getCurrentIndent() {
            int count = 0;
            int tempPos = pos;
            while (tempPos < input.length() && input.charAt(tempPos) == ' ') {
                count++;
                tempPos++;
            }
            return count;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read YAML lines until we see a line starting with '.'
        StringBuilder yamlBuilder = new StringBuilder();
        String line;

        while ((line = reader.readLine()) != null) {
            if (line.startsWith(".")) {
                break;
            }
            yamlBuilder.append(line).append("\n");
        }

        // The query is the line that started with '.'
        String query = line;

        // Parse YAML
        String yamlString = yamlBuilder.toString();
        YamlParser parser = new YamlParser(yamlString);
        Map<String, Object> root = parser.parse();

        // Process query
        String[] keys = query.substring(1).split("\\.");

        Object current = root;
        for (String key : keys) {
            if (!(current instanceof Map)) {
                current = null;
                break;
            }
            Map<String, Object> map = (Map<String, Object>) current;
            if (!map.containsKey(key)) {
                current = null;
                break;
            }
            current = map.get(key);
        }

        if (current == null) {
            System.out.println("no such property");
        } else if (current instanceof Map) {
            System.out.println("object");
        } else {
            System.out.println("string \"" + current + "\"");
        }
    }
}

