public class Main {
    static class Node {
        boolean isString;
        String value;
        Map<String, Node> map;

        static Node stringNode(String s) {
            Node n = new Node();
            n.isString = true;
            n.value = s;
            return n;
        }

        static Node objectNode() {
            Node n = new Node();
            n.isString = false;
            n.map = new HashMap<>();
            return n;
        }
    }

    static class Line {
        int indent;
        String key;
        String value; // null means object
        Line(int indent, String key, String value) {
            this.indent = indent;
            this.key = key;
            this.value = value;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null) return;

        int n = Integer.parseInt(first.trim());
        List<Line> lines = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            int indent = 0;
            while (indent < s.length() && s.charAt(indent) == ' ') indent++;

            String rest = s.substring(indent);
            int colon = rest.indexOf(':');
            String key = rest.substring(0, colon);

            String after = rest.substring(colon + 1);
            String value = null;
            if (!after.isEmpty()) {
                // Must be ": <string>"
                if (after.length() >= 1 && after.charAt(0) == ' ') {
                    value = after.substring(1);
                }
            }
            lines.add(new Line(indent, key, value));
        }

        String query = br.readLine();

        Node root = parse(lines);

        String[] parts = query.split("\\.");
        Node cur = root;
        boolean ok = true;
        for (String p : parts) {
            if (p.isEmpty()) continue;
            if (cur == null || cur.isString || !cur.map.containsKey(p)) {
                ok = false;
                break;
            }
            cur = cur.map.get(p);
        }

        if (!ok || cur == null) {
            System.out.println("no such property");
        } else if (cur.isString) {
            System.out.println("string \"" + cur.value + "\"");
        } else {
            System.out.println("object");
        }
    }

    static Node parse(List<Line> lines) {
        Node root = Node.objectNode();
        Deque<Node> nodeStack = new ArrayDeque<>();
        Deque<Integer> indentStack = new ArrayDeque<>();

        nodeStack.push(root);
        indentStack.push(-1);

        for (Line line : lines) {
            while (indentStack.peek() >= line.indent) {
                nodeStack.pop();
                indentStack.pop();
            }

            Node parent = nodeStack.peek();
            Node child;
            if (line.value == null) {
                child = Node.objectNode();
            } else {
                child = Node.stringNode(line.value);
            }
            parent.map.put(line.key, child);

            if (!child.isString) {
                nodeStack.push(child);
                indentStack.push(line.indent);
            }
        }

        return root;
    }
}

