import sys

def parse_yaml(lines):
    root = {}
    stack = [(-1, root)]  # (indent level, object)

    for raw in lines:
        if not raw.strip():
            continue

        indent = 0
        while indent < len(raw) and raw[indent] == ' ':
            indent += 1

        line = raw[indent:]
        if ':' not in line:
            continue

        key, rest = line.split(':', 1)
        key = key.strip()
        rest = rest.lstrip()

        while stack and stack[-1][0] >= indent:
            stack.pop()

        parent = stack[-1][1]

        if rest == "":
            obj = {}
            parent[key] = obj
            stack.append((indent, obj))
        else:
            parent[key] = rest

    return root

