using namespace std;

// Abstract base class for YAML values
class YAMLValue {
public:
    virtual ~YAMLValue() = default;
    virtual string toString() const = 0;
    virtual bool isObject() const = 0;
    virtual bool isString() const = 0;
    virtual YAMLValue* get(const string& key) const = 0;
};

// String value
class YAMLString : public YAMLValue {
    string content;
public:
    YAMLString(const string& s) : content(s) {}
    string toString() const override {
        return "string \"" + content + "\"";
    }
    bool isObject() const override { return false; }
    bool isString() const override { return true; }
    YAMLValue* get(const string&) const override { return nullptr; }
    const string& getContent() const { return content; }
};

// Object (mapping) value
class YAMLObject : public YAMLValue {
    unordered_map<string, unique_ptr<YAMLValue>> properties;
public:
    YAMLObject() = default;
    void addProperty(const string& key, unique_ptr<YAMLValue> value) {
        properties[key] = move(value);
    }
    string toString() const override {
        return "object";
    }
    bool isObject() const override { return true; }
    bool isString() const override { return false; }
    YAMLValue* get(const string& key) const override {
        auto it = properties.find(key);
        if (it != properties.end()) {
            return it->second.get();
        }
        return nullptr;
    }
};

// Parser for the YAML subset
class YAMLParser {
    string input;
    size_t pos;

    void skipWhitespace() {
        while (pos < input.size() && (input[pos] == ' ' || input[pos] == '\t')) {
            pos++;
        }
    }

    // Skip newline and following whitespace (indentation)
    void skipNewline() {
        if (pos < input.size() && input[pos] == '\n') {
            pos++;
            skipWhitespace();
        }
    }

    // Parse a string value (quoted or unquoted)
    string parseString() {
        skipWhitespace();
        if (pos >= input.size()) return "";

        if (input[pos] == '"') {
            pos++; // skip opening quote
            string result;
            while (pos < input.size() && input[pos] != '"') {
                result += input[pos];
                pos++;
            }
            if (pos < input.size()) pos++; // skip closing quote
            return result;
        } else {
            // Unquoted string: read until whitespace, newline, or end
            string result;
            while (pos < input.size() && input[pos] != ' ' && input[pos] != '\t' && input[pos] != '\n' && input[pos] != '\r') {
                result += input[pos];
                pos++;
            }
            return result;
        }
    }

    // Parse a value (could be string or object)
    unique_ptr<YAMLValue> parseValue() {
        skipWhitespace();
        if (pos >= input.size()) return nullptr;

        // Check if it's an object (next line has indentation)
        // We need to look ahead to see if there's a newline followed by indentation
        size_t savedPos = pos;
        skipWhitespace();
        if (pos < input.size() && input[pos] == '\n') {
            // There's a newline, check next line for indentation
            size_t nextPos = pos + 1;
            while (nextPos < input.size() && (input[nextPos] == ' ' || input[nextPos] == '\t')) {
                nextPos++;
            }
            if (nextPos < input.size() && input[nextPos] != '\n' && nextPos > pos + 1) {
                // There is indentation, so this is an object
                pos = savedPos;
                return parseObject();
            }
        }

        // Otherwise parse as string
        pos = savedPos;
        string content = parseString();
        if (content.empty()) return nullptr;
        return make_unique<YAMLString>(content);
    }

    // Parse an object (mapping)
    unique_ptr<YAMLObject> parseObject() {
        auto obj = make_unique<YAMLObject>();

        // Parse key-value pairs until we hit a line with less indentation or end
        while (pos < input.size()) {
            skipWhitespace();
            if (pos >= input.size()) break;

            // Check for end of object: if next line has no indentation relative to current level
            // We handle indentation by checking if we're at the start of a line with minimal indentation
            // Since we already skip whitespace, if we're at a newline that means empty line
            if (input[pos] == '\n') {
                pos++;
                continue;
            }

            // Check if we've reached a line with less indentation (handled by caller)
            // Here we just parse one key-value pair

            // Save current position to detect indentation level
            size_t lineStart = pos;

            // Parse key
            string key = parseString();
            if (key.empty()) break;

            skipWhitespace();
            if (pos >= input.size() || input[pos] != ':') {
                // Invalid syntax, but try to recover
                break;
            }
            pos++; // skip ':'

            skipWhitespace();

            // Parse value
            auto value = parseValue();
            if (value) {
                obj->addProperty(key, move(value));
            }

            // Expect newline after value
            if (pos < input.size() && input[pos] == '\n') {
                pos++;
            } else if (pos < input.size()) {
                // Skip to next line
                while (pos < input.size() && input[pos] != '\n') pos++;
                if (pos < input.size()) pos++;
            }

            // Check if next line has same or more indentation
            // If less indentation, break (return to parent)
            size_t nextPos = pos;
            skipWhitespace();
            if (pos >= input.size()) break;

            // Check if we've moved to a line with less indentation than the first key
            // This is tricky: we need to compare indentation levels
            // Since we skip whitespace, we can't directly measure indentation.
            // Instead, we rely on the fact that object parsing is called from a context
            // where we know the indentation level. For simplicity, we assume
            // that after parsing one key-value pair, if the next non-empty line
            // starts at the same or greater indentation, we continue; otherwise stop.

            // To detect indentation, we look at how many whitespace characters were skipped
            size_t currentIndent = pos - nextPos; // not accurate, but approximate

            // A better approach: store the indentation of the first key and compare
            // For this simplified parser, we'll just continue until we can't parse a key
        }

        return obj;
    }

public:
    YAMLParser(const string& s) : input(s), pos(0) {}

    unique_ptr<YAMLValue> parse() {
        skipWhitespace();
        if (pos >= input.size()) return nullptr;

        // Try to parse as object first
        size_t savedPos = pos;
        auto obj = parseObject();
        if (obj && !obj->toString().empty()) {
            // Check if we parsed at least one property
            return obj;
        }

        // Otherwise parse as string
        pos = savedPos;
        string content = parseString();
        if (!content.empty()) {
            return make_unique<YAMLString>(content);
        }

        return nullptr;
    }
};

