#include <bits/stdc++.h>
using namespace std;

struct Node {
    bool isString;
    string strVal;
    map<string, Node*> children;
};

// Parse lines starting at index `start` with expected indent `indent`
// Returns the index after parsing
int parseLines(vector<string>& lines, int start, int indent, Node* node) {
    int i = start;
    while (i < lines.size()) {
        string& line = lines[i];
        // Count leading spaces
        int spaces = 0;
        while (spaces < line.size() && line[spaces] == ' ') spaces++;
        if (spaces < indent) break; // back to parent
        if (spaces > indent) { i++; continue; } // shouldn't happen normally
        // Parse key
        int colon = line.find(':', spaces);
        string key = line.substr(spaces, colon - spaces);
        string rest = line.substr(colon + 1);
        // Trim rest
        int rs = 0;
        while (rs < rest.size() && rest[rs] == ' ') rs++;
        rest = rest.substr(rs);

        Node* child = new Node();
        if (rest.empty()) {
            // nested object
            child->isString = false;
            i++;
            i = parseLines(lines, i, indent + 2, child);
        } else {
            child->isString = true;
            child->strVal = rest;
            i++;
        }
        node->children[key] = child;
    }
    return i;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    bool isString = false;
    string val;
    map<string, Node*> child;
};

static inline int countIndent(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == ' ') i++;
    return i;
}

static inline string trimLeft(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == ' ') i++;
    return s.substr(i);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    string dummy;
    getline(cin, dummy);

    vector<string> lines(n);
    for (int i = 0; i < n; i++) getline(cin, lines[i]);

    string query;
    getline(cin, query);

    Node* root = new Node();

    // Stack of pairs: (indent level, node representing object at that level)
    vector<pair<int, Node*>> st;
    st.push_back({-1, root});

    for (int i = 0; i < n; i++) {
        string line = lines[i];
        int indent = countIndent(line);
        string s = trimLeft(line);

        while (!st.empty() && st.back().first >= indent) st.pop_back();

        Node* parent = st.back().second;

        size_t pos = s.find(':');
        string key = s.substr(0, pos);
        string rest = s.substr(pos + 1);

        Node* cur = new Node();

        if (!rest.empty() && rest[0] == ' ') {
            // string value
            cur->isString = true;
            cur->val = rest.substr(1);
        } else {
            // object value
            cur->isString = false;
        }

        parent->child[key] = cur;

        if (!cur->isString) {
            st.push_back({indent, cur});
        }
    }

    vector<string> keys;
    string cur;
    for (int i = 1; i < (int)query.size(); i++) { // skip initial '.'
        if (query[i] == '.') {
            keys.push_back(cur);
            cur.clear();
        } else {
            cur.push_back(query[i]);
        }
    }
    if (!cur.empty()) keys.push_back(cur);

    Node* p = root;
    bool ok = true;
    for (string &k : keys) {
        if (!p || p->isString || !p->child.count(k)) {
            ok = false;
            break;
        }
        p = p->child[k];
    }

    if (!ok) {
        cout << "no such property\n";
    } else if (p->isString) {
        cout << "string \"" << p->val << "\"\n";
    } else {
        cout << "object\n";
    }

    return 0;
}
